import pandas as pd,numpy as np,re
from sklearn.feature_extraction import DictVectorizer
from sklearn.linear_model import Ridge
from sklearn.model_selection import KFold,cross_val_predict
from sklearn.metrics import mean_squared_error
tr=pd.read_csv('b3_pvk_stack_pin_train.csv');po=pd.read_csv('b3_pvk_stack_pin_pool.csv');cols=list(tr.columns[:-1])
def feats(row,mode):
 d={}
 for c in cols:
  s=row[c];d[c+'='+s]=1
  if mode>0:
   for v in re.split(r' \| |; | >> ',s):d[c+'~'+v]=1
  if mode>1:
   if c in ['etl','htl']:
    for v in re.split(r' \| |; ',s):
     v=re.sub(r'-(?:np|c|mp|nw)$','',v)
     if v in ['C60','PCBM-60','PCBM-70']:v='fullerene'
     d[c+'class~'+v]=1
 return d
for mode in [0,1,2]:
 dv=DictVectorizer();X=dv.fit_transform([feats(r,mode) for _,r in tr.iterrows()]);Z=dv.transform([feats(r,mode) for _,r in po.iterrows()]);y=tr.target
 for a in [.5,2,10]:
  m=Ridge(alpha=a,solver='lsqr');cv=cross_val_predict(m,X,y,cv=KFold(5,shuffle=True,random_state=42));m.fit(X,y);p=m.predict(Z)
  print('\nMODE',mode,'alpha',a,'RMSE',round(mean_squared_error(y,cv)**.5,3))
  ii=np.argsort(-p)[:20];print(', '.join(f'{po.candidate_id[i]} {p[i]:.2f}' for i in ii))
